import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:repforge/domain/units/kilograms.dart';

part 'weight_entry.freezed.dart';

/// One dated body-weight record (requirement BCM-001).
@freezed
abstract class WeightEntry with _$WeightEntry {
  const factory WeightEntry({
    /// UUID v4, generated by the application, stable across devices.
    required String id,

    /// When the measurement was taken (device local time, stored as UTC).
    required DateTime recordedAt,
    required Kilograms weight,
    required DateTime createdAt,
    required DateTime updatedAt,
    String? note,
  }) = _WeightEntry;
}
